package com.wartec.flightqa;

import com.google.gson.*;
import com.wartec.wartecmod.port.content.*;
import net.minecraft.item.*;
import net.minecraft.block.Block;
import net.minecraftforge.oredict.OreDictionary;
import net.minecraftforge.fml.common.FMLCommonHandler;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Read-only registry census in a disposable world; no recipes are registered here. */
public final class RecipeCatalogQa {
    public void started() throws Exception {
        if(!Files.isRegularFile(Paths.get("FLIGHT_QA_ISOLATED")))throw new IllegalStateException("Not isolated");
        JsonObject out=new JsonObject();JsonArray rows=new JsonArray(),hbm=new JsonArray();
        for(Item item:Item.REGISTRY){String id=item.getRegistryName().toString();
            if(id.startsWith("hbm:")){hbm.add(id);continue;}
            if(!id.startsWith("wartecmod:"))continue;
            int count=item instanceof VariantItem?((VariantItem)item).getVariantCount():1;
            for(int meta=0;meta<count;meta++){ItemStack stack=new ItemStack(item,1,meta);JsonObject row=new JsonObject();row.addProperty("id",id);row.addProperty("meta",meta);row.addProperty("key",id+"@"+meta);row.addProperty("class",item.getClass().getSimpleName());row.addProperty("unlocalized",stack.getUnlocalizedName());row.addProperty("stack",stack.getMaxStackSize());row.addProperty("hidden",item.getCreativeTab()==null);row.addProperty("disabled",StrategicFeature.isDisabledItem(item) || item==WarTechContent.STRATEGIC_MISSILE && meta==1);rows.add(row);}
        }
        out.add("wartech",rows);out.add("hbm_item_ids",hbm);JsonObject ores=new JsonObject();for(String name:OreDictionary.getOreNames()){JsonArray stacks=new JsonArray();for(ItemStack stack:OreDictionary.getOres(name))stacks.add(stack.getItem().getRegistryName()+"@"+stack.getMetadata());ores.add(name,stacks);}out.add("ores",ores);
        JsonObject enums=new JsonObject();for(String className:Arrays.asList("com.hbm.items.ItemEnums$EnumCircuitType","com.hbm.items.ItemEnums$EnumPartType","com.hbm.items.machine.ItemStamp$StampType")){JsonObject values=new JsonObject();for(Object constant:Class.forName(className).getEnumConstants()){Enum e=(Enum)constant;values.addProperty(e.name(),e.ordinal());}enums.add(className,values);}out.add("enums",enums);
        out.addProperty("read_only_registry_census",true);out.addProperty("complete",true);
        JsonObject structure=new JsonObject();Map<String,Integer> counts=new TreeMap<>();for(com.wartec.wartecmod.port.silo.SiloStructure.Cell cell:com.wartec.wartecmod.port.silo.SiloStructure.cells(net.minecraft.util.EnumFacing.NORTH)){Block block=cell.state.getBlock();if(block==net.minecraft.init.Blocks.AIR)continue;String key=block.getRegistryName()+"@"+block.getMetaFromState(cell.state);counts.put(key,counts.getOrDefault(key,0)+1);}for(Map.Entry<String,Integer> e:counts.entrySet())structure.addProperty(e.getKey(),e.getValue());out.add("silo_structure_states",structure);
        JsonObject limits=new JsonObject();for(Item item:Item.REGISTRY)if(item.getRegistryName().getResourceDomain().equals("hbm"))limits.addProperty(item.getRegistryName().toString(),new ItemStack(item).getMaxStackSize());out.add("hbm_stack_limits",limits);
        if(Files.isRegularFile(Paths.get("recipe-design-manifest.json"))){JsonObject manifest=new JsonParser().parse(new String(Files.readAllBytes(Paths.get("recipe-design-manifest.json")),StandardCharsets.UTF_8)).getAsJsonObject();JsonArray checks=new JsonArray();for(JsonElement element:manifest.getAsJsonArray("recipes")){JsonObject recipe=element.getAsJsonObject();if(!recipe.get("machine").getAsString().equals("soldering"))continue;ItemStack[] slots=new ItemStack[6];Arrays.fill(slots,ItemStack.EMPTY);JsonArray inputs=recipe.getAsJsonArray("ingredients");JsonObject groups=recipe.getAsJsonObject("soldering_groups");int index=0;for(String group:Arrays.asList("toppings","pcb","solder")){int base=group.equals("toppings")?0:group.equals("pcb")?3:5;for(int i=0;i<groups.get(group).getAsInt();i++){JsonObject ingredient=inputs.get(index++).getAsJsonObject();String ref=ingredient.get("ref").getAsString();int amount=ingredient.get("count").getAsInt();if(ref.startsWith("ore:")){slots[base+i]=OreDictionary.getOres(ref.substring(4)).get(0).copy();slots[base+i].setCount(amount);}else{String[] bits=ref.split("@");slots[base+i]=new ItemStack(Item.REGISTRY.getObject(new net.minecraft.util.ResourceLocation(bits[0])),amount,Integer.parseInt(bits[1]));}}}com.hbm.inventory.recipes.SolderingRecipes.SolderingRecipe conflict=com.hbm.inventory.recipes.SolderingRecipes.getRecipe(slots);JsonObject result=new JsonObject();result.addProperty("output",recipe.get("output").getAsString());result.addProperty("native_collision",conflict!=null);if(conflict!=null)result.addProperty("native_result",conflict.output.getItem().getRegistryName()+"@"+conflict.output.getMetadata());checks.add(result);}out.add("proposed_soldering_match_checks",checks);}
        JsonArray presets=new JsonArray();for(com.wartec.wartecmod.port.cruise.CruisePartDefinition body:com.wartec.wartecmod.port.cruise.CruiseAirframes.bodies())for(boolean air:new boolean[]{false,true}){com.wartec.wartecmod.port.cruise.CruiseBuild build=com.wartec.wartecmod.port.cruise.CruiseBuild.starter(body);if(air)build.set(com.wartec.wartecmod.port.cruise.CruiseSlot.LAUNCH,com.wartec.wartecmod.port.cruise.CruisePartDefinition.LAUNCH_AIR);JsonObject preset=new JsonObject();preset.addProperty("id","cruise_"+body.getId()+(air?"_air":"_ground"));preset.addProperty("output","wartecmod:assembledcruise@0");JsonArray parts=new JsonArray();for(com.wartec.wartecmod.port.cruise.CruiseSlot slot:com.wartec.wartecmod.port.cruise.CruiseSlot.values())if(build.get(slot)!=null)parts.add("wartecmod:cruisemodule@"+build.get(slot).ordinal());preset.add("parts",parts);presets.add(preset);}
        for(com.wartec.wartecmod.port.uav.UavAirframe frame:com.wartec.wartecmod.port.uav.UavAirframe.values())for(boolean carrier:new boolean[]{false,true}){if(carrier && frame==com.wartec.wartecmod.port.uav.UavAirframe.ONE_WAY)continue;com.wartec.wartecmod.port.uav.UavBuild build=carrier?com.wartec.wartecmod.port.uav.UavBuild.cruiseCarrier(frame):com.wartec.wartecmod.port.uav.UavBuild.starter(frame);JsonObject preset=new JsonObject();preset.addProperty("id","uav_"+frame.name().toLowerCase()+(carrier?"_carrier":""));preset.addProperty("output","wartecmod:assembleduav@0");JsonArray parts=new JsonArray();for(com.wartec.wartecmod.port.uav.UavSlot slot:com.wartec.wartecmod.port.uav.UavSlot.values())if(build.get(slot)!=null)parts.add("wartecmod:uavmodule@"+build.get(slot).ordinal());preset.add("parts",parts);presets.add(preset);}out.add("presets",presets);
        Files.write(Paths.get("recipe-catalog.json"),new GsonBuilder().setPrettyPrinting().create().toJson(out).getBytes(StandardCharsets.UTF_8));System.out.println("RECIPECATALOG "+rows.size()+" WarTech metadata outputs; "+hbm.size()+" HBM items");FMLCommonHandler.instance().getMinecraftServerInstance().initiateShutdown();
    }
}
